class Item extends DataClass implements Insertable<Item> {
  final String key;
  final String name;

  /// Aksan/buyuk-kucuk harf duyarsiz arama icin onceden normalize edilmis ad.
  final String nameLower;

  /// Open5e dokuman anahtari (or. `srd-2024`).
  final String? document;
  final SourceType sourceType;

  /// Kaydin Open5e'den gelen tam JSON govdesi.
  final String dataJson;
  final String? category;
  final int? costCp;
  final double? weightLb;
  const Item({
    required this.key,
    required this.name,
    required this.nameLower,
    this.document,
    required this.sourceType,
    required this.dataJson,
    this.category,
    this.costCp,
    this.weightLb,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['key'] = Variable<String>(key);
    map['name'] = Variable<String>(name);
    map['name_lower'] = Variable<String>(nameLower);
    if (!nullToAbsent || document != null) {
      map['document'] = Variable<String>(document);
    }
    {
      map['source_type'] = Variable<String>(
        $ItemsTable.$convertersourceType.toSql(sourceType),
      );
    }
    map['data_json'] = Variable<String>(dataJson);
    if (!nullToAbsent || category != null) {
      map['category'] = Variable<String>(category);
    }
    if (!nullToAbsent || costCp != null) {
      map['cost_cp'] = Variable<int>(costCp);
    }
    if (!nullToAbsent || weightLb != null) {
      map['weight_lb'] = Variable<double>(weightLb);
    }
    return map;
  }

  ItemsCompanion toCompanion(bool nullToAbsent) {
    return ItemsCompanion(
      key: Value(key),
      name: Value(name),
      nameLower: Value(nameLower),
      document: document == null && nullToAbsent
          ? const Value.absent()
          : Value(document),
      sourceType: Value(sourceType),
      dataJson: Value(dataJson),
      category: category == null && nullToAbsent
          ? const Value.absent()
          : Value(category),
      costCp: costCp == null && nullToAbsent
          ? const Value.absent()
          : Value(costCp),
      weightLb: weightLb == null && nullToAbsent
          ? const Value.absent()
          : Value(weightLb),
    );
  }

  factory Item.fromJson(
    Map<String, dynamic> json, {
    ValueSerializer? serializer,
  }) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return Item(
      key: serializer.fromJson<String>(json['key']),
      name: serializer.fromJson<String>(json['name']),
      nameLower: serializer.fromJson<String>(json['nameLower']),
      document: serializer.fromJson<String?>(json['document']),
      sourceType: $ItemsTable.$convertersourceType.fromJson(
        serializer.fromJson<String>(json['sourceType']),
      ),
      dataJson: serializer.fromJson<String>(json['dataJson']),
      category: serializer.fromJson<String?>(json['category']),
      costCp: serializer.fromJson<int?>(json['costCp']),
      weightLb: serializer.fromJson<double?>(json['weightLb']),
    );
  }
  @override
  Map<String, dynamic> toJson({ValueSerializer? serializer}) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return <String, dynamic>{
      'key': serializer.toJson<String>(key),
      'name': serializer.toJson<String>(name),
      'nameLower': serializer.toJson<String>(nameLower),
      'document': serializer.toJson<String?>(document),
      'sourceType': serializer.toJson<String>(
        $ItemsTable.$convertersourceType.toJson(sourceType),
      ),
      'dataJson': serializer.toJson<String>(dataJson),
      'category': serializer.toJson<String?>(category),
      'costCp': serializer.toJson<int?>(costCp),
      'weightLb': serializer.toJson<double?>(weightLb),
    };
  }

  Item copyWith({
    String? key,
    String? name,
    String? nameLower,
    Value<String?> document = const Value.absent(),
    SourceType? sourceType,
    String? dataJson,
    Value<String?> category = const Value.absent(),
    Value<int?> costCp = const Value.absent(),
    Value<double?> weightLb = const Value.absent(),
  }) => Item(
    key: key ?? this.key,
    name: name ?? this.name,
    nameLower: nameLower ?? this.nameLower,
    document: document.present ? document.value : this.document,
    sourceType: sourceType ?? this.sourceType,
    dataJson: dataJson ?? this.dataJson,
    category: category.present ? category.value : this.category,
    costCp: costCp.present ? costCp.value : this.costCp,
    weightLb: weightLb.present ? weightLb.value : this.weightLb,
  );
  Item copyWithCompanion(ItemsCompanion data) {
    return Item(
      key: data.key.present ? data.key.value : this.key,
      name: data.name.present ? data.name.value : this.name,
      nameLower: data.nameLower.present ? data.nameLower.value : this.nameLower,
      document: data.document.present ? data.document.value : this.document,
      sourceType: data.sourceType.present
          ? data.sourceType.value
          : this.sourceType,
      dataJson: data.dataJson.present ? data.dataJson.value : this.dataJson,
      category: data.category.present ? data.category.value : this.category,
      costCp: data.costCp.present ? data.costCp.value : this.costCp,
      weightLb: data.weightLb.present ? data.weightLb.value : this.weightLb,
    );
  }

  @override
  String toString() {
    return (StringBuffer('Item(')
          ..write('key: $key, ')
          ..write('name: $name, ')
          ..write('nameLower: $nameLower, ')
          ..write('document: $document, ')
          ..write('sourceType: $sourceType, ')
          ..write('dataJson: $dataJson, ')
          ..write('category: $category, ')
          ..write('costCp: $costCp, ')
          ..write('weightLb: $weightLb')
          ..write(')'))
        .toString();
  }

