class Character extends DataClass implements Insertable<Character> {
  final String id;
  final String name;

  /// Bu karakteri masada oynayan kisinin adi; DM listede kimin kagidi
  /// oldugunu gormek icin yaziyor. Serbest metin, bos birakilabilir.
  final String? playerName;
  final String? speciesKey;
  final String? backgroundKey;
  final String? alignment;

  /// Irk/background/ASI etkileri UYGULANMIS nihai puanlar. Sihirbaz bunlari
  /// hesaplayip yaziyor; kagit uzerinde tek dogruluk kaynagi bu olsun diye
  /// "taban puan + bonuslar" ayrimi tasinmiyor.
  final int strength;
  final int dexterity;
  final int constitution;
  final int intelligence;
  final int wisdom;
  final int charisma;
  final int experiencePoints;
  final int hitPointsMax;
  final int hitPointsCurrent;
  final int temporaryHitPoints;

  /// Basarili/basarisiz olum kurtarma atislari (0-3).
  final int deathSaveSuccesses;
  final int deathSaveFailures;

  /// 2024 kurallarinda her seviye d20 atislarina -1 veriyor.
  final int exhaustion;
  final bool inspiration;

  /// Cebindeki para, bakir cinsinden.
  final int coinsCp;

  /// Zirh/kalkan disi bir kaynaktan gelen AC (or. sihirli etki). Doluysa
  /// hesaplanan degerin yerine gecer.
  final int? armorClassOverride;
  final int? speedOverride;

  /// Aktif durum efektleri (JSON dizisi).
  final String conditionsJson;

  /// Harcanmis hit dice: sinif anahtari -> adet.
  final String hitDiceUsedJson;

  /// Oyuncunun hazir buyu listesinde kac degisiklik yapabilecegi.
  ///
  /// Uzun dinlenmede (Cleric/Druid/Paladin/Wizard/Artificer) listenin tamami
  /// kadar, seviye atlayinca (Bard/Ranger/Sorcerer/Warlock) bir tane veriliyor.
  /// Bos yere yeni buyu eklemek hak harcamaz; yalnizca SECILI bir buyuyu
  /// listeden cikarmak harcar.
  final int spellChangesAvailable;

  /// Su an konsantrasyon tutulan buyunun adi; yoksa null.
  ///
  /// Hasar alinca CON kurtarmasi gerektigi icin masada takip edilmesi gereken
  /// tek "acik buyu" bilgisi bu.
  final String? concentrationSpell;

  /// Ekipman yuvasi sinirlarindan VARSAYILANDAN FARKLI olanlar
  /// (`EquipSlot.name` -> adet, -1 sinirsiz). Yalnizca elle degistirilenler
  /// yaziliyor ki varsayilan degisirse dokunulmamis yuvalar onu izlesin.
  final String slotCapacitiesJson;

  /// Harcanmis buyu yuvalari: yuva seviyesi -> adet.
  final String spellSlotsUsedJson;
  final String? portraitPath;

  /// Serbest hikaye/gecmis metni.
  final String notes;

  /// 2024 kagidindaki kisilik alanlari ve gorunus tarifi.
  final String appearance;
  final String personality;
  final String ideal;
  final String bond;
  final String flaw;
  final DateTime createdAt;
  final DateTime updatedAt;
  const Character({
    required this.id,
    required this.name,
    this.playerName,
    this.speciesKey,
    this.backgroundKey,
    this.alignment,
    required this.strength,
    required this.dexterity,
    required this.constitution,
    required this.intelligence,
    required this.wisdom,
    required this.charisma,
    required this.experiencePoints,
    required this.hitPointsMax,
    required this.hitPointsCurrent,
    required this.temporaryHitPoints,
    required this.deathSaveSuccesses,
    required this.deathSaveFailures,
    required this.exhaustion,
    required this.inspiration,
    required this.coinsCp,
    this.armorClassOverride,
    this.speedOverride,
    required this.conditionsJson,
    required this.hitDiceUsedJson,
    required this.spellChangesAvailable,
    this.concentrationSpell,
    required this.slotCapacitiesJson,
    required this.spellSlotsUsedJson,
    this.portraitPath,
    required this.notes,
    required this.appearance,
    required this.personality,
    required this.ideal,
    required this.bond,
    required this.flaw,
    required this.createdAt,
    required this.updatedAt,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['name'] = Variable<String>(name);
    if (!nullToAbsent || playerName != null) {
      map['player_name'] = Variable<String>(playerName);
    }
    if (!nullToAbsent || speciesKey != null) {
      map['species_key'] = Variable<String>(speciesKey);
    }
    if (!nullToAbsent || backgroundKey != null) {
      map['background_key'] = Variable<String>(backgroundKey);
    }
    if (!nullToAbsent || alignment != null) {
      map['alignment'] = Variable<String>(alignment);
    }
    map['strength'] = Variable<int>(strength);
    map['dexterity'] = Variable<int>(dexterity);
    map['constitution'] = Variable<int>(constitution);
    map['intelligence'] = Variable<int>(intelligence);
    map['wisdom'] = Variable<int>(wisdom);
    map['charisma'] = Variable<int>(charisma);
    map['experience_points'] = Variable<int>(experiencePoints);
    map['hit_points_max'] = Variable<int>(hitPointsMax);
    map['hit_points_current'] = Variable<int>(hitPointsCurrent);
    map['temporary_hit_points'] = Variable<int>(temporaryHitPoints);
    map['death_save_successes'] = Variable<int>(deathSaveSuccesses);
    map['death_save_failures'] = Variable<int>(deathSaveFailures);
    map['exhaustion'] = Variable<int>(exhaustion);
    map['inspiration'] = Variable<bool>(inspiration);
    map['coins_cp'] = Variable<int>(coinsCp);
    if (!nullToAbsent || armorClassOverride != null) {
      map['armor_class_override'] = Variable<int>(armorClassOverride);
    }
    if (!nullToAbsent || speedOverride != null) {
      map['speed_override'] = Variable<int>(speedOverride);
    }
    map['conditions_json'] = Variable<String>(conditionsJson);
    map['hit_dice_used_json'] = Variable<String>(hitDiceUsedJson);
    map['spell_changes_available'] = Variable<int>(spellChangesAvailable);
    if (!nullToAbsent || concentrationSpell != null) {
      map['concentration_spell'] = Variable<String>(concentrationSpell);
    }
    map['slot_capacities_json'] = Variable<String>(slotCapacitiesJson);
    map['spell_slots_used_json'] = Variable<String>(spellSlotsUsedJson);
    if (!nullToAbsent || portraitPath != null) {
      map['portrait_path'] = Variable<String>(portraitPath);
    }
    map['notes'] = Variable<String>(notes);
    map['appearance'] = Variable<String>(appearance);
    map['personality'] = Variable<String>(personality);
    map['ideal'] = Variable<String>(ideal);
    map['bond'] = Variable<String>(bond);
    map['flaw'] = Variable<String>(flaw);
    map['created_at'] = Variable<DateTime>(createdAt);
    map['updated_at'] = Variable<DateTime>(updatedAt);
    return map;
  }

  CharactersCompanion toCompanion(bool nullToAbsent) {
    return CharactersCompanion(
      id: Value(id),
      name: Value(name),
      playerName: playerName == null && nullToAbsent
          ? const Value.absent()
          : Value(playerName),
      speciesKey: speciesKey == null && nullToAbsent
          ? const Value.absent()
          : Value(speciesKey),
      backgroundKey: backgroundKey == null && nullToAbsent
          ? const Value.absent()
          : Value(backgroundKey),
      alignment: alignment == null && nullToAbsent
          ? const Value.absent()
          : Value(alignment),
      strength: Value(strength),
      dexterity: Value(dexterity),
      constitution: Value(constitution),
      intelligence: Value(intelligence),
      wisdom: Value(wisdom),
      charisma: Value(charisma),
      experiencePoints: Value(experiencePoints),
      hitPointsMax: Value(hitPointsMax),
      hitPointsCurrent: Value(hitPointsCurrent),
      temporaryHitPoints: Value(temporaryHitPoints),
      deathSaveSuccesses: Value(deathSaveSuccesses),
      deathSaveFailures: Value(deathSaveFailures),
      exhaustion: Value(exhaustion),
      inspiration: Value(inspiration),
      coinsCp: Value(coinsCp),
      armorClassOverride: armorClassOverride == null && nullToAbsent
          ? const Value.absent()
          : Value(armorClassOverride),
      speedOverride: speedOverride == null && nullToAbsent
          ? const Value.absent()
          : Value(speedOverride),
      conditionsJson: Value(conditionsJson),
      hitDiceUsedJson: Value(hitDiceUsedJson),
      spellChangesAvailable: Value(spellChangesAvailable),
      concentrationSpell: concentrationSpell == null && nullToAbsent
          ? const Value.absent()
          : Value(concentrationSpell),
      slotCapacitiesJson: Value(slotCapacitiesJson),
      spellSlotsUsedJson: Value(spellSlotsUsedJson),
      portraitPath: portraitPath == null && nullToAbsent
