      map['item_key'] = Variable<String>(itemKey);
    }
    if (!nullToAbsent || magicItemKey != null) {
      map['magic_item_key'] = Variable<String>(magicItemKey);
    }
    if (!nullToAbsent || customName != null) {
      map['custom_name'] = Variable<String>(customName);
    }
    if (!nullToAbsent || customDesc != null) {
      map['custom_desc'] = Variable<String>(customDesc);
    }
    map['quantity'] = Variable<int>(quantity);
    map['equipped'] = Variable<bool>(equipped);
    if (!nullToAbsent || slot != null) {
      map['slot'] = Variable<String>(slot);
    }
    map['attuned'] = Variable<bool>(attuned);
    map['sort_order'] = Variable<int>(sortOrder);
    return map;
  }

  CharacterItemsCompanion toCompanion(bool nullToAbsent) {
    return CharacterItemsCompanion(
      id: Value(id),
      characterId: Value(characterId),
      itemKey: itemKey == null && nullToAbsent
          ? const Value.absent()
          : Value(itemKey),
      magicItemKey: magicItemKey == null && nullToAbsent
          ? const Value.absent()
          : Value(magicItemKey),
      customName: customName == null && nullToAbsent
