class CharacterFeature extends DataClass
    implements Insertable<CharacterFeature> {
  final String id;
  final String characterId;

  /// Kutuphanedeki feature/feat anahtari; homebrew'da bos.
  final String? featureKey;
  final String name;
  final String description;

  /// Nereden geldigi: sinif anahtari, tur anahtari, `feat`, `manual`.
  final String source;
  final int? gainedAtLevel;

  /// Sinirli kullanimli yetenekler icin (or. Second Wind 1/kisa dinlenme).
  final int? usesMax;
  final int usesSpent;
  const CharacterFeature({
    required this.id,
    required this.characterId,
    this.featureKey,
    required this.name,
    required this.description,
    required this.source,
    this.gainedAtLevel,
    this.usesMax,
    required this.usesSpent,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['character_id'] = Variable<String>(characterId);
    if (!nullToAbsent || featureKey != null) {
      map['feature_key'] = Variable<String>(featureKey);
    }
    map['name'] = Variable<String>(name);
    map['description'] = Variable<String>(description);
    map['source'] = Variable<String>(source);
    if (!nullToAbsent || gainedAtLevel != null) {
      map['gained_at_level'] = Variable<int>(gainedAtLevel);
    }
    if (!nullToAbsent || usesMax != null) {
      map['uses_max'] = Variable<int>(usesMax);
    }
    map['uses_spent'] = Variable<int>(usesSpent);
    return map;
  }

  CharacterFeaturesCompanion toCompanion(bool nullToAbsent) {
    return CharacterFeaturesCompanion(
      id: Value(id),
      characterId: Value(characterId),
      featureKey: featureKey == null && nullToAbsent
          ? const Value.absent()
          : Value(featureKey),
      name: Value(name),
      description: Value(description),
      source: Value(source),
      gainedAtLevel: gainedAtLevel == null && nullToAbsent
          ? const Value.absent()
          : Value(gainedAtLevel),
      usesMax: usesMax == null && nullToAbsent
          ? const Value.absent()
          : Value(usesMax),
      usesSpent: Value(usesSpent),
    );
  }

  factory CharacterFeature.fromJson(
    Map<String, dynamic> json, {
    ValueSerializer? serializer,
  }) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return CharacterFeature(
      id: serializer.fromJson<String>(json['id']),
      characterId: serializer.fromJson<String>(json['characterId']),
      featureKey: serializer.fromJson<String?>(json['featureKey']),
      name: serializer.fromJson<String>(json['name']),
      description: serializer.fromJson<String>(json['description']),
      source: serializer.fromJson<String>(json['source']),
      gainedAtLevel: serializer.fromJson<int?>(json['gainedAtLevel']),
      usesMax: serializer.fromJson<int?>(json['usesMax']),
      usesSpent: serializer.fromJson<int>(json['usesSpent']),
    );
  }
  @override
  Map<String, dynamic> toJson({ValueSerializer? serializer}) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return <String, dynamic>{
      'id': serializer.toJson<String>(id),
      'characterId': serializer.toJson<String>(characterId),
      'featureKey': serializer.toJson<String?>(featureKey),
      'name': serializer.toJson<String>(name),
      'description': serializer.toJson<String>(description),
      'source': serializer.toJson<String>(source),
      'gainedAtLevel': serializer.toJson<int?>(gainedAtLevel),
      'usesMax': serializer.toJson<int?>(usesMax),
      'usesSpent': serializer.toJson<int>(usesSpent),
    };
  }

  CharacterFeature copyWith({
    String? id,
    String? characterId,
    Value<String?> featureKey = const Value.absent(),
    String? name,
    String? description,
    String? source,
    Value<int?> gainedAtLevel = const Value.absent(),
    Value<int?> usesMax = const Value.absent(),
    int? usesSpent,
  }) => CharacterFeature(
    id: id ?? this.id,
    characterId: characterId ?? this.characterId,
    featureKey: featureKey.present ? featureKey.value : this.featureKey,
    name: name ?? this.name,
    description: description ?? this.description,
    source: source ?? this.source,
    gainedAtLevel: gainedAtLevel.present
        ? gainedAtLevel.value
        : this.gainedAtLevel,
    usesMax: usesMax.present ? usesMax.value : this.usesMax,
    usesSpent: usesSpent ?? this.usesSpent,
  );
  CharacterFeature copyWithCompanion(CharacterFeaturesCompanion data) {
    return CharacterFeature(
      id: data.id.present ? data.id.value : this.id,
      characterId: data.characterId.present
          ? data.characterId.value
          : this.characterId,
      featureKey: data.featureKey.present
          ? data.featureKey.value
          : this.featureKey,
      name: data.name.present ? data.name.value : this.name,
      description: data.description.present
          ? data.description.value
          : this.description,
      source: data.source.present ? data.source.value : this.source,
      gainedAtLevel: data.gainedAtLevel.present
          ? data.gainedAtLevel.value
          : this.gainedAtLevel,
      usesMax: data.usesMax.present ? data.usesMax.value : this.usesMax,
      usesSpent: data.usesSpent.present ? data.usesSpent.value : this.usesSpent,
    );
  }

  @override
  String toString() {
    return (StringBuffer('CharacterFeature(')
          ..write('id: $id, ')
          ..write('characterId: $characterId, ')
          ..write('featureKey: $featureKey, ')
          ..write('name: $name, ')
          ..write('description: $description, ')
          ..write('source: $source, ')
          ..write('gainedAtLevel: $gainedAtLevel, ')
          ..write('usesMax: $usesMax, ')
          ..write('usesSpent: $usesSpent')
          ..write(')'))
        .toString();
  }

  @override
  int get hashCode => Object.hash(
    id,
    characterId,
    featureKey,
    name,
    description,
    source,
    gainedAtLevel,
    usesMax,
    usesSpent,
  );
  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      (other is CharacterFeature &&
          other.id == this.id &&
          other.characterId == this.characterId &&
          other.featureKey == this.featureKey &&
          other.name == this.name &&
          other.description == this.description &&
          other.source == this.source &&
          other.gainedAtLevel == this.gainedAtLevel &&
          other.usesMax == this.usesMax &&
          other.usesSpent == this.usesSpent);
}

