class Combatant extends DataClass implements Insertable<Combatant> {
  final String id;
  final String encounterId;
  final CombatantKind kind;
  final String name;

  /// Oyuncu karakterlerinde karakter kaydi, canavarlarda kutuphane anahtari.
  final String? characterId;
  final String? monsterKey;
  final int initiative;

  /// Esit initiative'de sirayi sabitlemek icin; ayrica surukleyerek
  /// yeniden siralamada kullanilir.
  final int sortOrder;
  final int hitPointsMax;
  final int hitPointsCurrent;
  final int temporaryHitPoints;
  final int? armorClass;

  /// Aktif durumlar (JSON dizisi).
  final String conditionsJson;

  /// Tur basina efsanevi eylem hakki; null = bu katilimcinin efsanevi eylemi
  /// yok. Veri setinde hak sayisi YAZMADIGI icin canavar eklenirken
  /// [kDefaultLegendaryActionsPerRound] ile doldurulur, DM degistirebilir.
  final int? legendaryMax;

  /// Bu turda harcanan efsanevi eylem; katilimcinin turu BASLAYINCA sifirlanir
  /// (D&D kurali: efsanevi eylemler canavarin turunun basinda tazelenir).
  final int legendarySpent;

  /// Gunluk efsanevi direnc (Legendary Resistance N/Day); null = yok.
  /// Tur basinda SIFIRLANMAZ -- gunluk bir kaynak, DM elle yeniler.
  final int? legendaryResistMax;
  final int legendaryResistSpent;

  /// Konsantrasyon takibi: DM'in en cok unuttugu sey.
  final bool concentrating;
  final String? concentrationNote;

  /// Bu turda REAKSIYONUNU kullandi mi?
  ///
  /// Masada en cok unutulan kaynak: reaksiyon tur basina bir tanedir ve
  /// katilimcinin SIRASI GELINCE tazelenir (D&D kurali: "tur basinizin
  /// baslangicina kadar"). [CombatRepository.advanceTurn] sifirliyor.
  final bool reactionUsed;

  /// Hasar turu savunmalari: `{"resist":[],"immune":[],"vulnerable":[]}`.
  ///
  /// Canavar eklenirken kutuphane verisinden dolduruluyor; DM elle
  /// duzenleyebiliyor. Tek JSON sutun cunku uc liste de yalnizca hasar
  /// uygulanirken birlikte okunuyor, hicbiri ayri sorgulanmiyor.
  final String defensesJson;

  /// Olum kurtarma atislari.
  ///
  /// Oyuncu karakterlerinde karakter kaydiyla ESITLENIR (orasi ana kayit);
  /// canavar/adhoc katilimcilar icin tek yer burasi. Can 0'a dusunce arayuz
  /// sayaci kendiliginden aciyor.
  final int deathSaveSuccesses;
  final int deathSaveFailures;
  final bool defeated;
  final String note;
  const Combatant({
    required this.id,
    required this.encounterId,
    required this.kind,
    required this.name,
    this.characterId,
    this.monsterKey,
    required this.initiative,
    required this.sortOrder,
    required this.hitPointsMax,
    required this.hitPointsCurrent,
    required this.temporaryHitPoints,
    this.armorClass,
    required this.conditionsJson,
    this.legendaryMax,
    required this.legendarySpent,
    this.legendaryResistMax,
    required this.legendaryResistSpent,
    required this.concentrating,
    this.concentrationNote,
    required this.reactionUsed,
    required this.defensesJson,
    required this.deathSaveSuccesses,
    required this.deathSaveFailures,
    required this.defeated,
    required this.note,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['encounter_id'] = Variable<String>(encounterId);
    {
      map['kind'] = Variable<String>(
        $CombatantsTable.$converterkind.toSql(kind),
      );
    }
    map['name'] = Variable<String>(name);
    if (!nullToAbsent || characterId != null) {
      map['character_id'] = Variable<String>(characterId);
    }
    if (!nullToAbsent || monsterKey != null) {
      map['monster_key'] = Variable<String>(monsterKey);
    }
    map['initiative'] = Variable<int>(initiative);
    map['sort_order'] = Variable<int>(sortOrder);
    map['hit_points_max'] = Variable<int>(hitPointsMax);
    map['hit_points_current'] = Variable<int>(hitPointsCurrent);
    map['temporary_hit_points'] = Variable<int>(temporaryHitPoints);
    if (!nullToAbsent || armorClass != null) {
      map['armor_class'] = Variable<int>(armorClass);
    }
    map['conditions_json'] = Variable<String>(conditionsJson);
    if (!nullToAbsent || legendaryMax != null) {
      map['legendary_max'] = Variable<int>(legendaryMax);
    }
    map['legendary_spent'] = Variable<int>(legendarySpent);
    if (!nullToAbsent || legendaryResistMax != null) {
      map['legendary_resist_max'] = Variable<int>(legendaryResistMax);
    }
    map['legendary_resist_spent'] = Variable<int>(legendaryResistSpent);
    map['concentrating'] = Variable<bool>(concentrating);
    if (!nullToAbsent || concentrationNote != null) {
      map['concentration_note'] = Variable<String>(concentrationNote);
    }
    map['reaction_used'] = Variable<bool>(reactionUsed);
    map['defenses_json'] = Variable<String>(defensesJson);
    map['death_save_successes'] = Variable<int>(deathSaveSuccesses);
    map['death_save_failures'] = Variable<int>(deathSaveFailures);
    map['defeated'] = Variable<bool>(defeated);
    map['note'] = Variable<String>(note);
    return map;
  }

  CombatantsCompanion toCompanion(bool nullToAbsent) {
    return CombatantsCompanion(
      id: Value(id),
      encounterId: Value(encounterId),
      kind: Value(kind),
      name: Value(name),
      characterId: characterId == null && nullToAbsent
          ? const Value.absent()
          : Value(characterId),
      monsterKey: monsterKey == null && nullToAbsent
          ? const Value.absent()
          : Value(monsterKey),
      initiative: Value(initiative),
      sortOrder: Value(sortOrder),
      hitPointsMax: Value(hitPointsMax),
      hitPointsCurrent: Value(hitPointsCurrent),
      temporaryHitPoints: Value(temporaryHitPoints),
      armorClass: armorClass == null && nullToAbsent
          ? const Value.absent()
          : Value(armorClass),
      conditionsJson: Value(conditionsJson),
      legendaryMax: legendaryMax == null && nullToAbsent
          ? const Value.absent()
          : Value(legendaryMax),
      legendarySpent: Value(legendarySpent),
      legendaryResistMax: legendaryResistMax == null && nullToAbsent
          ? const Value.absent()
          : Value(legendaryResistMax),
      legendaryResistSpent: Value(legendaryResistSpent),
      concentrating: Value(concentrating),
      concentrationNote: concentrationNote == null && nullToAbsent
          ? const Value.absent()
          : Value(concentrationNote),
      reactionUsed: Value(reactionUsed),
      defensesJson: Value(defensesJson),
      deathSaveSuccesses: Value(deathSaveSuccesses),
      deathSaveFailures: Value(deathSaveFailures),
      defeated: Value(defeated),
      note: Value(note),
    );
  }

  factory Combatant.fromJson(
    Map<String, dynamic> json, {
    ValueSerializer? serializer,
  }) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return Combatant(
      id: serializer.fromJson<String>(json['id']),
      encounterId: serializer.fromJson<String>(json['encounterId']),
      kind: $CombatantsTable.$converterkind.fromJson(
        serializer.fromJson<String>(json['kind']),
      ),
      name: serializer.fromJson<String>(json['name']),
      characterId: serializer.fromJson<String?>(json['characterId']),
      monsterKey: serializer.fromJson<String?>(json['monsterKey']),
      initiative: serializer.fromJson<int>(json['initiative']),
      sortOrder: serializer.fromJson<int>(json['sortOrder']),
      hitPointsMax: serializer.fromJson<int>(json['hitPointsMax']),
      hitPointsCurrent: serializer.fromJson<int>(json['hitPointsCurrent']),
      temporaryHitPoints: serializer.fromJson<int>(json['temporaryHitPoints']),
      armorClass: serializer.fromJson<int?>(json['armorClass']),
      conditionsJson: serializer.fromJson<String>(json['conditionsJson']),
      legendaryMax: serializer.fromJson<int?>(json['legendaryMax']),
      legendarySpent: serializer.fromJson<int>(json['legendarySpent']),
      legendaryResistMax: serializer.fromJson<int?>(json['legendaryResistMax']),
      legendaryResistSpent: serializer.fromJson<int>(
        json['legendaryResistSpent'],
      ),
      concentrating: serializer.fromJson<bool>(json['concentrating']),
      concentrationNote: serializer.fromJson<String?>(
        json['concentrationNote'],
      ),
      reactionUsed: serializer.fromJson<bool>(json['reactionUsed']),
      defensesJson: serializer.fromJson<String>(json['defensesJson']),
      deathSaveSuccesses: serializer.fromJson<int>(json['deathSaveSuccesses']),
      deathSaveFailures: serializer.fromJson<int>(json['deathSaveFailures']),
      defeated: serializer.fromJson<bool>(json['defeated']),
      note: serializer.fromJson<String>(json['note']),
    );
  }
  @override
  Map<String, dynamic> toJson({ValueSerializer? serializer}) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return <String, dynamic>{
      'id': serializer.toJson<String>(id),
      'encounterId': serializer.toJson<String>(encounterId),
      'kind': serializer.toJson<String>(
        $CombatantsTable.$converterkind.toJson(kind),
      ),
      'name': serializer.toJson<String>(name),
      'characterId': serializer.toJson<String?>(characterId),
      'monsterKey': serializer.toJson<String?>(monsterKey),
      'initiative': serializer.toJson<int>(initiative),
      'sortOrder': serializer.toJson<int>(sortOrder),
      'hitPointsMax': serializer.toJson<int>(hitPointsMax),
      'hitPointsCurrent': serializer.toJson<int>(hitPointsCurrent),
      'temporaryHitPoints': serializer.toJson<int>(temporaryHitPoints),
      'armorClass': serializer.toJson<int?>(armorClass),
      'conditionsJson': serializer.toJson<String>(conditionsJson),
      'legendaryMax': serializer.toJson<int?>(legendaryMax),
      'legendarySpent': serializer.toJson<int>(legendarySpent),
      'legendaryResistMax': serializer.toJson<int?>(legendaryResistMax),
      'legendaryResistSpent': serializer.toJson<int>(legendaryResistSpent),
      'concentrating': serializer.toJson<bool>(concentrating),
      'concentrationNote': serializer.toJson<String?>(concentrationNote),
