  }

  Combatant copyWith({
    String? id,
    String? encounterId,
    CombatantKind? kind,
    String? name,
    Value<String?> characterId = const Value.absent(),
    Value<String?> monsterKey = const Value.absent(),
    int? initiative,
    int? sortOrder,
    int? hitPointsMax,
    int? hitPointsCurrent,
    int? temporaryHitPoints,
    Value<int?> armorClass = const Value.absent(),
    String? conditionsJson,
    Value<int?> legendaryMax = const Value.absent(),
    int? legendarySpent,
    Value<int?> legendaryResistMax = const Value.absent(),
    int? legendaryResistSpent,
    bool? concentrating,
    Value<String?> concentrationNote = const Value.absent(),
    bool? reactionUsed,
    String? defensesJson,
    int? deathSaveSuccesses,
    int? deathSaveFailures,
    bool? defeated,
    String? note,
  }) => Combatant(
    id: id ?? this.id,
    encounterId: encounterId ?? this.encounterId,
    kind: kind ?? this.kind,
    name: name ?? this.name,
    characterId: characterId.present ? characterId.value : this.characterId,
    monsterKey: monsterKey.present ? monsterKey.value : this.monsterKey,
    initiative: initiative ?? this.initiative,
    sortOrder: sortOrder ?? this.sortOrder,
    hitPointsMax: hitPointsMax ?? this.hitPointsMax,
    hitPointsCurrent: hitPointsCurrent ?? this.hitPointsCurrent,
    temporaryHitPoints: temporaryHitPoints ?? this.temporaryHitPoints,
