class Npc extends DataClass implements Insertable<Npc> {
  final String id;
  final String name;
  final String role;
  final String description;
  final String race;
  final String gender;
  final String age;
  final String alignment;
  final String appearance;
  final String personality;
  final String ideal;
  final String bond;
  final String flaw;
  final String hook;

  /// DM'e ozel notlar.
  final String secretNotes;

  /// Bagli oldugu canavar stat blogu (varsa) -- savasa dogrudan eklemek icin.
  final String? monsterKey;
  final String? portraitPath;

  /// Dunya grafigindeki (DM-only) serbest konum.
  final double? graphX;
  final double? graphY;

  /// Dugum (küre) gorsel boyutu (DM-only). Null = varsayilan (yer=30, npc=21).
  final double? nodeRadius;
  final DateTime createdAt;
  const Npc({
    required this.id,
    required this.name,
    required this.role,
    required this.description,
    required this.race,
    required this.gender,
    required this.age,
    required this.alignment,
    required this.appearance,
    required this.personality,
    required this.ideal,
    required this.bond,
    required this.flaw,
    required this.hook,
    required this.secretNotes,
    this.monsterKey,
    this.portraitPath,
    this.graphX,
    this.graphY,
    this.nodeRadius,
    required this.createdAt,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['name'] = Variable<String>(name);
    map['role'] = Variable<String>(role);
    map['description'] = Variable<String>(description);
    map['race'] = Variable<String>(race);
    map['gender'] = Variable<String>(gender);
    map['age'] = Variable<String>(age);
    map['alignment'] = Variable<String>(alignment);
    map['appearance'] = Variable<String>(appearance);
    map['personality'] = Variable<String>(personality);
    map['ideal'] = Variable<String>(ideal);
    map['bond'] = Variable<String>(bond);
    map['flaw'] = Variable<String>(flaw);
    map['hook'] = Variable<String>(hook);
    map['secret_notes'] = Variable<String>(secretNotes);
    if (!nullToAbsent || monsterKey != null) {
      map['monster_key'] = Variable<String>(monsterKey);
    }
    if (!nullToAbsent || portraitPath != null) {
      map['portrait_path'] = Variable<String>(portraitPath);
    }
    if (!nullToAbsent || graphX != null) {
      map['graph_x'] = Variable<double>(graphX);
    }
    if (!nullToAbsent || graphY != null) {
      map['graph_y'] = Variable<double>(graphY);
    }
    if (!nullToAbsent || nodeRadius != null) {
      map['node_radius'] = Variable<double>(nodeRadius);
    }
    map['created_at'] = Variable<DateTime>(createdAt);
    return map;
  }

  NpcsCompanion toCompanion(bool nullToAbsent) {
    return NpcsCompanion(
      id: Value(id),
      name: Value(name),
      role: Value(role),
      description: Value(description),
      race: Value(race),
      gender: Value(gender),
      age: Value(age),
      alignment: Value(alignment),
      appearance: Value(appearance),
      personality: Value(personality),
      ideal: Value(ideal),
      bond: Value(bond),
      flaw: Value(flaw),
      hook: Value(hook),
      secretNotes: Value(secretNotes),
      monsterKey: monsterKey == null && nullToAbsent
          ? const Value.absent()
          : Value(monsterKey),
      portraitPath: portraitPath == null && nullToAbsent
          ? const Value.absent()
          : Value(portraitPath),
      graphX: graphX == null && nullToAbsent
          ? const Value.absent()
          : Value(graphX),
      graphY: graphY == null && nullToAbsent
          ? const Value.absent()
          : Value(graphY),
      nodeRadius: nodeRadius == null && nullToAbsent
          ? const Value.absent()
          : Value(nodeRadius),
      createdAt: Value(createdAt),
    );
  }

  factory Npc.fromJson(
