class Journey extends DataClass implements Insertable<Journey> {
  final String id;

  /// Rotanin cizildigi harita (yer). Olcek oradan okunur.
  final String locationId;

  /// Duraklar: `[{"x":0.1,"y":0.2,"label":"Kale","pinId":"..."}]`.
  ///
  /// Pin id'si SAKLANIR ama koordinat da yazilir: durak haritadan serbestce
  /// tiklanmis bir ara nokta olabilir (pini yoktur) ve pin sonradan silinse
  /// bile yolculugun uzunlugu degismemelidir.
  final String stopsJson;

  /// Haritada karsiligi olmayan elle girilen ek mesafe.
  final double extraMiles;

  /// `TravelSpeed.key`; ozel hizda `travelCustomSpeed`.
  final String speedKey;

  /// Ozel hizin mil/saat degeri (yalnizca ozel hizda anlamli).
  final double? customMph;
  final double hoursPerDay;
  final bool encountersOn;
  final String? tableId;
  final int threshold;
  final int checksPerDay;

  /// Rotanin toplam uzunlugu (mil). Baslangicta hesaplanip DONDURULUR: harita
  /// olcegi ya da pinler yolculuk sirasinda degisse de "kalan yol" tutarsiz
  /// olmasin.
  final double totalMiles;

  /// Su ana kadar gidilen yol (mil).
  final double milesTravelled;

  /// Kac karsilasma kontrolu yapildi. Sonraki dilimin nerede basladigini
  /// belirler; [milesTravelled]'dan TURETILEMEZ cunku karsilasma bir dilimin
  /// ORTASINDA olur.
  final int checksDone;

  /// Takvime simdiye kadar islenmis gun sayisi. Her adimda yalnizca FARK
  /// ilerletilir; yoksa duraklayip devam eden yolculuk gunleri iki kez sayardi.
  final int daysAdvanced;

  /// Ilerledikce takvim de ilerlesin mi?
  final bool advanceCalendar;

  /// Partiyi DURDURAN karsilasma:
  /// `{"day":2,"checkIndex":1,"check":19,"tableRoll":7,"text":"..."}`.
  /// Null = yolda serbest ilerleniyor.
  final String? pendingEncounterJson;

  /// Yolculuk boyunca yasanan tum karsilasmalar (ayni bicimde bir dizi).
  /// Varista oturum gunlugune bu liste yazilir.
  final String encounterLogJson;
  final bool done;
  final DateTime createdAt;
  const Journey({
    required this.id,
    required this.locationId,
    required this.stopsJson,
    required this.extraMiles,
    required this.speedKey,
    this.customMph,
    required this.hoursPerDay,
    required this.encountersOn,
    this.tableId,
    required this.threshold,
    required this.checksPerDay,
    required this.totalMiles,
    required this.milesTravelled,
    required this.checksDone,
    required this.daysAdvanced,
    required this.advanceCalendar,
    this.pendingEncounterJson,
    required this.encounterLogJson,
    required this.done,
    required this.createdAt,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['location_id'] = Variable<String>(locationId);
    map['stops_json'] = Variable<String>(stopsJson);
    map['extra_miles'] = Variable<double>(extraMiles);
    map['speed_key'] = Variable<String>(speedKey);
    if (!nullToAbsent || customMph != null) {
      map['custom_mph'] = Variable<double>(customMph);
    }
    map['hours_per_day'] = Variable<double>(hoursPerDay);
    map['encounters_on'] = Variable<bool>(encountersOn);
    if (!nullToAbsent || tableId != null) {
      map['table_id'] = Variable<String>(tableId);
    }
    map['threshold'] = Variable<int>(threshold);
    map['checks_per_day'] = Variable<int>(checksPerDay);
    map['total_miles'] = Variable<double>(totalMiles);
    map['miles_travelled'] = Variable<double>(milesTravelled);
    map['checks_done'] = Variable<int>(checksDone);
    map['days_advanced'] = Variable<int>(daysAdvanced);
    map['advance_calendar'] = Variable<bool>(advanceCalendar);
    if (!nullToAbsent || pendingEncounterJson != null) {
      map['pending_encounter_json'] = Variable<String>(pendingEncounterJson);
    }
    map['encounter_log_json'] = Variable<String>(encounterLogJson);
    map['done'] = Variable<bool>(done);
    map['created_at'] = Variable<DateTime>(createdAt);
    return map;
  }

  JourneysCompanion toCompanion(bool nullToAbsent) {
    return JourneysCompanion(
      id: Value(id),
      locationId: Value(locationId),
      stopsJson: Value(stopsJson),
      extraMiles: Value(extraMiles),
      speedKey: Value(speedKey),
      customMph: customMph == null && nullToAbsent
          ? const Value.absent()
          : Value(customMph),
      hoursPerDay: Value(hoursPerDay),
      encountersOn: Value(encountersOn),
      tableId: tableId == null && nullToAbsent
          ? const Value.absent()
          : Value(tableId),
      threshold: Value(threshold),
      checksPerDay: Value(checksPerDay),
      totalMiles: Value(totalMiles),
      milesTravelled: Value(milesTravelled),
      checksDone: Value(checksDone),
      daysAdvanced: Value(daysAdvanced),
      advanceCalendar: Value(advanceCalendar),
      pendingEncounterJson: pendingEncounterJson == null && nullToAbsent
          ? const Value.absent()
          : Value(pendingEncounterJson),
      encounterLogJson: Value(encounterLogJson),
      done: Value(done),
      createdAt: Value(createdAt),
    );
  }

  factory Journey.fromJson(
    Map<String, dynamic> json, {
    ValueSerializer? serializer,
  }) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return Journey(
      id: serializer.fromJson<String>(json['id']),
      locationId: serializer.fromJson<String>(json['locationId']),
      stopsJson: serializer.fromJson<String>(json['stopsJson']),
      extraMiles: serializer.fromJson<double>(json['extraMiles']),
      speedKey: serializer.fromJson<String>(json['speedKey']),
      customMph: serializer.fromJson<double?>(json['customMph']),
      hoursPerDay: serializer.fromJson<double>(json['hoursPerDay']),
      encountersOn: serializer.fromJson<bool>(json['encountersOn']),
      tableId: serializer.fromJson<String?>(json['tableId']),
      threshold: serializer.fromJson<int>(json['threshold']),
      checksPerDay: serializer.fromJson<int>(json['checksPerDay']),
      totalMiles: serializer.fromJson<double>(json['totalMiles']),
      milesTravelled: serializer.fromJson<double>(json['milesTravelled']),
      checksDone: serializer.fromJson<int>(json['checksDone']),
      daysAdvanced: serializer.fromJson<int>(json['daysAdvanced']),
      advanceCalendar: serializer.fromJson<bool>(json['advanceCalendar']),
      pendingEncounterJson: serializer.fromJson<String?>(
        json['pendingEncounterJson'],
      ),
      encounterLogJson: serializer.fromJson<String>(json['encounterLogJson']),
      done: serializer.fromJson<bool>(json['done']),
      createdAt: serializer.fromJson<DateTime>(json['createdAt']),
    );
  }
  @override
  Map<String, dynamic> toJson({ValueSerializer? serializer}) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return <String, dynamic>{
      'id': serializer.toJson<String>(id),
      'locationId': serializer.toJson<String>(locationId),
      'stopsJson': serializer.toJson<String>(stopsJson),
      'extraMiles': serializer.toJson<double>(extraMiles),
      'speedKey': serializer.toJson<String>(speedKey),
      'customMph': serializer.toJson<double?>(customMph),
      'hoursPerDay': serializer.toJson<double>(hoursPerDay),
      'encountersOn': serializer.toJson<bool>(encountersOn),
      'tableId': serializer.toJson<String?>(tableId),
      'threshold': serializer.toJson<int>(threshold),
      'checksPerDay': serializer.toJson<int>(checksPerDay),
      'totalMiles': serializer.toJson<double>(totalMiles),
      'milesTravelled': serializer.toJson<double>(milesTravelled),
      'checksDone': serializer.toJson<int>(checksDone),
      'daysAdvanced': serializer.toJson<int>(daysAdvanced),
      'advanceCalendar': serializer.toJson<bool>(advanceCalendar),
      'pendingEncounterJson': serializer.toJson<String?>(pendingEncounterJson),
      'encounterLogJson': serializer.toJson<String>(encounterLogJson),
      'done': serializer.toJson<bool>(done),
      'createdAt': serializer.toJson<DateTime>(createdAt),
    };
  }

  Journey copyWith({
    String? id,
    String? locationId,
    String? stopsJson,
    double? extraMiles,
    String? speedKey,
    Value<double?> customMph = const Value.absent(),
    double? hoursPerDay,
    bool? encountersOn,
    Value<String?> tableId = const Value.absent(),
    int? threshold,
    int? checksPerDay,
    double? totalMiles,
    double? milesTravelled,
    int? checksDone,
    int? daysAdvanced,
    bool? advanceCalendar,
    Value<String?> pendingEncounterJson = const Value.absent(),
    String? encounterLogJson,
    bool? done,
    DateTime? createdAt,
  }) => Journey(
    id: id ?? this.id,
    locationId: locationId ?? this.locationId,
    stopsJson: stopsJson ?? this.stopsJson,
    extraMiles: extraMiles ?? this.extraMiles,
    speedKey: speedKey ?? this.speedKey,
    customMph: customMph.present ? customMph.value : this.customMph,
    hoursPerDay: hoursPerDay ?? this.hoursPerDay,
    encountersOn: encountersOn ?? this.encountersOn,
    tableId: tableId.present ? tableId.value : this.tableId,
    threshold: threshold ?? this.threshold,
    checksPerDay: checksPerDay ?? this.checksPerDay,
    totalMiles: totalMiles ?? this.totalMiles,
    milesTravelled: milesTravelled ?? this.milesTravelled,
    checksDone: checksDone ?? this.checksDone,
    daysAdvanced: daysAdvanced ?? this.daysAdvanced,
    advanceCalendar: advanceCalendar ?? this.advanceCalendar,
    pendingEncounterJson: pendingEncounterJson.present
        ? pendingEncounterJson.value
        : this.pendingEncounterJson,
    encounterLogJson: encounterLogJson ?? this.encounterLogJson,
    done: done ?? this.done,
    createdAt: createdAt ?? this.createdAt,
  );
  Journey copyWithCompanion(JourneysCompanion data) {
    return Journey(
      id: data.id.present ? data.id.value : this.id,
      locationId: data.locationId.present
          ? data.locationId.value
          : this.locationId,
      stopsJson: data.stopsJson.present ? data.stopsJson.value : this.stopsJson,
      extraMiles: data.extraMiles.present
          ? data.extraMiles.value
          : this.extraMiles,
      speedKey: data.speedKey.present ? data.speedKey.value : this.speedKey,
      customMph: data.customMph.present ? data.customMph.value : this.customMph,
      hoursPerDay: data.hoursPerDay.present
          ? data.hoursPerDay.value
          : this.hoursPerDay,
      encountersOn: data.encountersOn.present
          ? data.encountersOn.value
          : this.encountersOn,
      tableId: data.tableId.present ? data.tableId.value : this.tableId,
      threshold: data.threshold.present ? data.threshold.value : this.threshold,
      checksPerDay: data.checksPerDay.present
          ? data.checksPerDay.value
          : this.checksPerDay,
      totalMiles: data.totalMiles.present
          ? data.totalMiles.value
          : this.totalMiles,
      milesTravelled: data.milesTravelled.present
          ? data.milesTravelled.value
          : this.milesTravelled,
      checksDone: data.checksDone.present
          ? data.checksDone.value
          : this.checksDone,
      daysAdvanced: data.daysAdvanced.present
          ? data.daysAdvanced.value
          : this.daysAdvanced,
      advanceCalendar: data.advanceCalendar.present
          ? data.advanceCalendar.value
          : this.advanceCalendar,
      pendingEncounterJson: data.pendingEncounterJson.present
          ? data.pendingEncounterJson.value
          : this.pendingEncounterJson,
      encounterLogJson: data.encounterLogJson.present
          ? data.encounterLogJson.value
          : this.encounterLogJson,
      done: data.done.present ? data.done.value : this.done,
      createdAt: data.createdAt.present ? data.createdAt.value : this.createdAt,
    );
  }

  @override
  String toString() {
    return (StringBuffer('Journey(')
          ..write('id: $id, ')
          ..write('locationId: $locationId, ')
          ..write('stopsJson: $stopsJson, ')
          ..write('extraMiles: $extraMiles, ')
          ..write('speedKey: $speedKey, ')
          ..write('customMph: $customMph, ')
          ..write('hoursPerDay: $hoursPerDay, ')
          ..write('encountersOn: $encountersOn, ')
          ..write('tableId: $tableId, ')
          ..write('threshold: $threshold, ')
          ..write('checksPerDay: $checksPerDay, ')
          ..write('totalMiles: $totalMiles, ')
          ..write('milesTravelled: $milesTravelled, ')
          ..write('checksDone: $checksDone, ')
          ..write('daysAdvanced: $daysAdvanced, ')
          ..write('advanceCalendar: $advanceCalendar, ')
          ..write('pendingEncounterJson: $pendingEncounterJson, ')
          ..write('encounterLogJson: $encounterLogJson, ')
          ..write('done: $done, ')
          ..write('createdAt: $createdAt')
          ..write(')'))
        .toString();
  }

  @override
  int get hashCode => Object.hash(
    id,
