  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      (other is Journey &&
          other.id == this.id &&
          other.locationId == this.locationId &&
          other.stopsJson == this.stopsJson &&
          other.extraMiles == this.extraMiles &&
          other.speedKey == this.speedKey &&
