class ChronicleEvent extends DataClass implements Insertable<ChronicleEvent> {
  final String id;
  final String title;

  /// Zengin metin (Kayıtlar'daki satır içi biçimlendirmenin aynısı:
  /// `**kalın**`, `[[wiki]]`, `/r 2d6`, `/monster(...)`).
  final String body;
  final int year;
  final int? monthIndex;
  final int? day;
  final int? endYear;
  final int? endMonthIndex;
  final int? endDay;

  /// Bağlı çağ (yoksa yıla göre kendiliğinden gruplanır). FK yok — çağ
  /// silinince olay yetim kalmaz, yalnız gruplaması düşer.
  final String? eraId;

  /// Serbest kategori ("savaş", "antlaşma", "felaket"...). Filtrelemede
  /// kullanılır; sabit bir liste dayatılmaz.
  final String category;
  final int? color;

  /// DM'e özel: oyuncuların bilmediği olay. (Tarihçe zaten oyunculara
  /// gönderilmiyor; bu bayrak DM'in kendi ayrımı ve ileride paylaşım
  /// eklenirse hazır.)
  final bool secret;

  /// Uzun metin için bir Kayıtlar sayfasına bağlanabilir.
  final String? codexPageId;

  /// İsteğe bağlı dünya bağlantıları.
  final String? locationId;
  final String? npcId;
  final DateTime createdAt;
  const ChronicleEvent({
    required this.id,
    required this.title,
    required this.body,
    required this.year,
    this.monthIndex,
    this.day,
    this.endYear,
    this.endMonthIndex,
    this.endDay,
    this.eraId,
    required this.category,
    this.color,
    required this.secret,
    this.codexPageId,
    this.locationId,
    this.npcId,
    required this.createdAt,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['title'] = Variable<String>(title);
    map['body'] = Variable<String>(body);
    map['year'] = Variable<int>(year);
    if (!nullToAbsent || monthIndex != null) {
      map['month_index'] = Variable<int>(monthIndex);
    }
    if (!nullToAbsent || day != null) {
      map['day'] = Variable<int>(day);
    }
    if (!nullToAbsent || endYear != null) {
      map['end_year'] = Variable<int>(endYear);
    }
    if (!nullToAbsent || endMonthIndex != null) {
      map['end_month_index'] = Variable<int>(endMonthIndex);
    }
    if (!nullToAbsent || endDay != null) {
      map['end_day'] = Variable<int>(endDay);
    }
    if (!nullToAbsent || eraId != null) {
      map['era_id'] = Variable<String>(eraId);
    }
    map['category'] = Variable<String>(category);
    if (!nullToAbsent || color != null) {
      map['color'] = Variable<int>(color);
    }
    map['secret'] = Variable<bool>(secret);
    if (!nullToAbsent || codexPageId != null) {
      map['codex_page_id'] = Variable<String>(codexPageId);
    }
    if (!nullToAbsent || locationId != null) {
      map['location_id'] = Variable<String>(locationId);
    }
    if (!nullToAbsent || npcId != null) {
      map['npc_id'] = Variable<String>(npcId);
    }
    map['created_at'] = Variable<DateTime>(createdAt);
    return map;
  }

  ChronicleEventsCompanion toCompanion(bool nullToAbsent) {
    return ChronicleEventsCompanion(
      id: Value(id),
      title: Value(title),
      body: Value(body),
      year: Value(year),
      monthIndex: monthIndex == null && nullToAbsent
          ? const Value.absent()
          : Value(monthIndex),
      day: day == null && nullToAbsent ? const Value.absent() : Value(day),
      endYear: endYear == null && nullToAbsent
          ? const Value.absent()
          : Value(endYear),
      endMonthIndex: endMonthIndex == null && nullToAbsent
          ? const Value.absent()
          : Value(endMonthIndex),
      endDay: endDay == null && nullToAbsent
          ? const Value.absent()
          : Value(endDay),
