          : Value(color),
      secret: Value(secret),
      codexPageId: codexPageId == null && nullToAbsent
          ? const Value.absent()
          : Value(codexPageId),
      locationId: locationId == null && nullToAbsent
          ? const Value.absent()
          : Value(locationId),
      npcId: npcId == null && nullToAbsent
          ? const Value.absent()
          : Value(npcId),
      createdAt: Value(createdAt),
    );
  }

